<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserFederatedIdentityCreateEvent extends UserFederatedIdentityEvent implements PublicEvent
{
    public function __construct(
        UserFederatedIdentity $payload
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-federated-identity.create';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return [];
    }
}
